// Does a param name invented by brace-blind signature splitting create a
// DATA_FLOWS edge that has no basis in the source?
func TestScratchProbeSpuriousEdge(t *testing.T) {
	repo := t.TempDir()
	// `y` is NOT a parameter of caller — it is a field of the object literal
	// default, and separately a package-level variable that caller forwards.
	writeFile(t, repo, "spurious.js", `const y = loadGlobal();

function caller(opts = {x: 1, y: 2}) {
  return sink(y);
}

function sink(v) { return v; }
function loadGlobal() { return 7; }
`)

	var buf bytes.Buffer
	err := StreamSnapshot(t.Context(), repo, "v", ProviderSnapshotOptions{Worktree: true}, func(rec any) error {
		data, marshalErr := json.Marshal(rec)
		if marshalErr != nil {
			return marshalErr
		}
		buf.Write(data)
		buf.WriteByte('\n')
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	fmt.Println("PARAMS of caller:", sortedKeys(toSet(parameterNames("function caller(opts = {x: 1, y: 2})"))))
	for _, line := range strings.Split(buf.String(), "\n") {
		if strings.Contains(line, "DATA_FLOWS") {
			fmt.Println("EDGE:", line)
		}
	}
}

func toSet(m map[string]bool) map[string]struct{} {
	out := map[string]struct{}{}
	for k := range m {
		out[k] = struct{}{}
	}
	return out
}

