// splitSimpleArguments splits an argument or parameter list on its top-level
// commas. Commas nested inside brackets or quotes do not separate arguments:
// a Zig `options: struct { scripts: u8, git_commit: u8 }` parameter, a Go
// `map[string]int`, or a JS `{x: 1, y: 2}` default is ONE entry, not several.
// Splitting them blindly used to invent parameter names out of struct fields
// and stray closing braces, which then fabricated DATA_FLOWS edges claiming a
// caller parameter was forwarded when it was a module-level identifier.
// Angle brackets are deliberately not tracked — `a < b` is a comparison far
// more often than a generic in the sources this runs over.
func splitSimpleArguments(args string) []string {
	if strings.TrimSpace(args) == "" {
		return nil
	}
	var out []string
	depth := 0
	var quote rune
	start := 0
	for index, char := range args {
		switch {
		case quote != 0:
			if char == quote {
				quote = 0
			}
		case char == '\'' || char == '"' || char == '`':
			quote = char
		case char == '(' || char == '[' || char == '{':
			depth++
		case char == ')' || char == ']' || char == '}':
			if depth > 0 {
				depth--
			}
		case char == ',' && depth == 0:
			if part := strings.TrimSpace(args[start:index]); part != "" {
				out = append(out, part)
			}
			start = index + len(string(char))
		}
	}
	if part := strings.TrimSpace(args[start:]); part != "" {
		out = append(out, part)
	}
	return out
}

