			fmt.Printf("%-8s NO SPEC\n", tc.path)
			continue
		}
		parser := sitter.NewParser()
		parser.SetLanguage(spec.grammar)
		tree, err := parser.ParseCtx(context.Background(), nil, []byte(tc.src))
		if err != nil || tree == nil {
			fmt.Printf("%-8s parse failed\n", tc.path)
			parser.Close()
			continue
		}
