			if list != nil || n == nil || n.IsNull() {
				return
			}
			if p := n.ChildByFieldName("parameters"); p != nil && !p.IsNull() {
				list, owner = p, n.Type()+"[field]"
				return
			}
			for i := 0; i < int(n.NamedChildCount()); i++ {
				if c := n.NamedChild(i); c != nil && !c.IsNull() && paramNodeTypes[c.Type()] {
					list, owner = c, n.Type()+"[child]"
					return
				}
			}
			for i := 0; i < int(n.NamedChildCount()); i++ {
				walk(n.NamedChild(i))
			}
		}
		walk(tree.RootNode())
		if list == nil {
			fmt.Printf("%-8s %-12s NO PARAM LIST FOUND\n", tc.path, spec.language)
		} else {
			fmt.Printf("%-8s %-12s list=%s via %s\n", tc.path, spec.language, list.Type(), owner)
			for i := 0; i < int(list.NamedChildCount()); i++ {
				c := list.NamedChild(i)
				fields := ""
				for j := 0; j < int(c.ChildCount()); j++ {
