func TestScratchProbeExtraction(t *testing.T) {
	cases := []struct {
		path, src string
		want      string
	}{
		{"a.go", "package p\nfunc (c *Client) Do(ctx Context, name, urlStr string, opts map[string]int) error { return nil }\n", "[ctx name urlStr opts]"},
		{"a.py", "def f(a, b=1, c: int = 2, *args, **kw):\n    pass\n", "[a b c args kw]"},
		{"a.rs", "fn f(&self, a: u8, b: Vec<(u8, u8)>) -> u8 { a }\n", "[a b]"},
		{"a.java", "class C { void m(int a, Map<String, Integer> b, String... c) {} }\n", "[a b c]"},
		{"a.rb", "def f(a, b = 1, *c, **d)\nend\n", "[a b c d]"},
		{"a.zig", "fn caller(b: *Build, options: struct { scripts: u8, git_commit: u8 }) void {}\n", "[b options]"},
		{"a.c", "int f(int a, char *b, void (*cb)(int)) { return a; }\n", "[a b cb]"},
		{"a.cs", "class C { void M(int a, Dictionary<string, int> b, params int[] c) {} }\n", "[a b c]"},
		{"a.php", "<?php function f($a, int $b = 1, ...$c) {} ?>\n", "[a b c]"},
		{"a.kt", "fun f(a: Int, b: Map<String, Int> = mapOf()) {}\n", "[a b]"},
		{"a.scala", "def f(a: Int, b: Map[String, Int]): Int = a\n", "[a b]"},
		{"a.swift", "func f(_ a: Int, label b: [String: Int]) {}\n", "[a b]"},
		{"a.lua", "function f(a, b, ...) end\n", "[a b]"},
		{"a.dart", "int f(int a, int b) => a;\n", "[a b]"},
		{"a.cpp", "int f(int a, std::map<int, int> b) { return a; }\n", "[a b]"},
	}
	for _, tc := range cases {
		spec, ok := languageForPath(tc.path)
		if !ok {
			fmt.Printf("%-8s NO SPEC\n", tc.path)
			continue
		}
		parser := sitter.NewParser()
		parser.SetLanguage(spec.grammar)
		tree, _ := parser.ParseCtx(context.Background(), nil, []byte(tc.src))
		var got []string
		var known bool
		var walk func(n *sitter.Node)
		walk = func(n *sitter.Node) {
			if known || n == nil || n.IsNull() {
				return
			}
			if names, ok := astParameterNames(n, []byte(tc.src)); ok && len(names) > 0 {
				got, known = names, true
				return
			}
			for i := 0; i < int(n.NamedChildCount()); i++ {
				walk(n.NamedChild(i))
			}
		}
		walk(tree.RootNode())
		status := "OK  "
		if fmt.Sprint(got) != tc.want {
			status = "FAIL"
		}
		fmt.Printf("%s %-8s %-12s got=%-28v want=%v\n", status, tc.path, spec.language, fmt.Sprint(got), tc.want)
		tree.Close()
		parser.Close()
	}
}
